export function configureEdgeToEdgeEnforcement(
  config: ResourceXMLConfig,
  disableEdgeToEdgeEnforcement: boolean
): ResourceXMLConfig {
  const { style = [] } = config.modResults.resources;

  const disableEdgeToEdgeEnforcementItem = {
    _: 'true',
    $: {
      name: OPT_OUT_EDGE_TO_EDGE_ATTRIBUTE,
      'tools:targetApi': '35',
    },
  };

  const mainThemeIndex = style.findIndex(({ $ }) => $.name === 'AppTheme');

  if (mainThemeIndex === -1) {
    return config;
  }

  const existingItem = style[mainThemeIndex].item.filter(
    ({ $ }) => $.name !== OPT_OUT_EDGE_TO_EDGE_ATTRIBUTE
  );

  if (disableEdgeToEdgeEnforcement) {
    existingItem.push(disableEdgeToEdgeEnforcementItem);
  }
  if (!config.modResults.resources.style) {
    return config;
  }

  config.modResults.resources.style[mainThemeIndex].item = existingItem;
  return config;
}

export type GradlePropertiesConfig = ExportedConfigWithProps<
  AndroidConfig.Properties.PropertiesItem[]
>;

withEdgeToEdge: ConfigPlugin<{ projectRoot: string }> = (config, { projectRoot }) => {
  return applyEdgeToEdge(config, projectRoot);
}

export function applyEdgeToEdge(config: ExpoConfig, projectRoot: string): ExpoConfig {
  // NOTE(@kitten): Override for SDK 54 only. This is deprecated/removed but `false` is still technically accepted just for SDK 54
  const raw_edgeToEdgeEnabled = config.android?.edgeToEdgeEnabled as boolean | undefined;

  if (raw_edgeToEdgeEnabled === false) {
    WarningAggregator.addWarningAndroid(
      TAG,
      '`edgeToEdgeEnabled` field is explicitly set to false in the project app config. In Android 16+ (targetSdkVersion 36) it is no longer be possible to disable edge-to-edge. Learn more:',
      'https://expo.fyi/edge-to-edge-rollout'
    );
  }

  const edgeToEdgeEnabled = raw_edgeToEdgeEnabled !== false;

  config = withEdgeToEdgeEnabledGradleProperties(config, { edgeToEdgeEnabled });
  // Enable/disable edge-to-edge enforcement
  config = withConfigureEdgeToEdgeEnforcement(config, {
    disableEdgeToEdgeEnforcement: !edgeToEdgeEnabled,
  });

  config = withEnforceNavigationBarContrast(
    config,
    config.androidNavigationBar?.enforceContrast !== false
  );

  // We always restore the default theme in case the project has a leftover react-native-edge-to-edge theme from SDK 53.
  // If they are using react-native-edge-to-edge config plugin it'll be reapplied later.
  return withRestoreDefaultTheme(config);
}

