    EXPO_EDGE_TO_EDGE_ENABLED_GRADLE_PROPERTY_KEY,
    edgeToEdgeEnabled ? 'true' : 'false',
    EXPO_EDGE_TO_EDGE_ENABLED_GRADLE_PROPERTY_COMMENT
  );

  return configureGradleProperty(
    config,
    REACT_EDGE_TO_EDGE_ENABLED_GRADLE_PROPERTY_KEY,
