      colorMatched: IBBoolean;
      initialViewController: string;
    },
    {
      device: IBDevice[];
      dependencies: unknown[];
      scenes: {
        scene: IBScene[];
      }[];
      resources: {
        image: IBResourceImage[];
        namedColor?: IBItem<{ name: string }, { color: IBResourceNamedColor[] }>[];
      }[];
    }
  >;
};

export function createConstraint(
  [firstItem, firstAttribute]: [string, ConstraintAttribute],
  [secondItem, secondAttribute]: [string, ConstraintAttribute],
  constant?: number
): IBConstraint {
  return {
    $: {
      firstItem,
      firstAttribute,
      secondItem,
      secondAttribute,
      constant,
      // Prevent updating between runs
      id: createConstraintId(firstItem, firstAttribute, secondItem, secondAttribute),
    },
  };
}

export function createConstraintId(...attributes: string[]) {
  return crypto.createHash('sha1').update(attributes.join('-')).digest('hex');
}

export function removeImageFromSplashScreen(
  xml: IBSplashScreenDocument,
  { imageName }: { imageName: string }
) {
  const mainView = xml.document.scenes[0].scene[0].objects[0].viewController[0].view[0];

  debug(`Remove all splash screen image elements`);

  removeExisting(mainView.subviews[0].imageView, IMAGE_ID);

  // Remove Constraints
  getAbsoluteConstraints(IMAGE_ID, CONTAINER_ID).forEach((constraint) => {
    // <constraint firstItem="EXPO-SplashScreen" firstAttribute="top" secondItem="EXPO-ContainerView" secondAttribute="top" id="2VS-Uz-0LU"/>
    const constrainsArray = mainView.constraints[0].constraint;
    removeExisting(constrainsArray, constraint);
  });

  // Remove resource
  xml.document.resources[0].image = xml.document.resources[0].image ?? [];
  const imageSection = xml.document.resources[0].image;

  const existingImageIndex = imageSection.findIndex((image) => image.$.name === imageName);
  if (existingImageIndex && existingImageIndex > -1) {
    imageSection?.splice(existingImageIndex, 1);
  }
  return xml;
}

export function applyImageToSplashScreenXML(
  xml: IBSplashScreenDocument,
  {
    imageName,
    contentMode,
    backgroundColor,
    enableFullScreenImage,
    imageWidth = 100,
  }: {
    imageName: string;
    contentMode: ImageContentMode;
    backgroundColor: string;
    enableFullScreenImage: boolean;
    imageWidth?: number;
  }
): IBSplashScreenDocument {
  const mainView = xml.document.scenes[0].scene[0].objects[0].viewController[0].view[0];
  const width = enableFullScreenImage ? 414 : imageWidth;
  const height = enableFullScreenImage ? 736 : imageWidth;
  const x = enableFullScreenImage ? 0 : (mainView.rect[0].$.width - width) / 2;
  const y = enableFullScreenImage ? 0 : (mainView.rect[0].$.height - height) / 2;

  const imageView: IBImageView = {
    $: {
      id: IMAGE_ID,
      userLabel: imageName,
      image: imageName,
      contentMode,
      clipsSubviews: true,
      userInteractionEnabled: false,
      translatesAutoresizingMaskIntoConstraints: false,
    },
    rect: [
      {
        $: {
          key: 'frame',
          x,
          y,
          width,
          height,
        },
      },
    ],
  };

  // Add ImageView
  ensureUniquePush(mainView.subviews[0].imageView, imageView);

  mainView.constraints[0].constraint = [];

  // Add Constraints
  getAbsoluteConstraints(IMAGE_ID, CONTAINER_ID, enableFullScreenImage).forEach(
    (constraint: IBConstraint) => {
      const constrainsArray = mainView.constraints[0].constraint;
      ensureUniquePush(constrainsArray, constraint);
    }
  );

  // Clear existing images
  xml.document.resources[0].image = [];

  // Add resource
  const imageSection = xml.document.resources[0].image;
  imageSection.push({
    $: {
      name: imageName,
      width,
      height,
    },
  });

  // Clear existing color
  mainView.color = [];
  // Add background color
  const colorSection = mainView.color;

  colorSection.push({
    $: {
      key: 'backgroundColor',
      name: 'SplashScreenBackground',
    },
  });

  // Clear existing named colors
  xml.document.resources[0].namedColor = [];

  const namedColorSection = xml.document.resources[0].namedColor;
  // Add background named color reference
  const color = parseColor(backgroundColor);

  namedColorSection.push({
    $: {
      name: 'SplashScreenBackground',
    },
    color: [
      {
        $: {
          alpha: '1.000',
          blue: color.rgb.blue,
          green: color.rgb.green,
          red: color.rgb.red,
          customColorSpace: 'sRGB',
          colorSpace: 'custom',
        },
      },
    ],
  });

  return xml;
}

export function ensureUniquePush<TItem extends { $: { id: string } }>(array: TItem[], item: TItem) {
  if (!array) return array;
  removeExisting(array, item);
  array.push(item);
  return array;
}

export function removeExisting<TItem extends { $: { id: string } }>(
  array: TItem[],
  item: TItem | string
) {
  const id = typeof item === 'string' ? item : item.$?.id;
  const existingItem = array?.findIndex((existingItem) => existingItem.$.id === id);
  if (existingItem > -1) {
    debug(`Removing existing IB item with id ${id}, from: %O`, array);
    array.splice(existingItem, 1);
  }
  return array;
}

export function toString(xml: any): string {
  const builder = new Builder({
    // @ts-expect-error: untyped
    preserveChildrenOrder: true,
    xmldec: {
      version: '1.0',
      encoding: 'UTF-8',
    },
    renderOpts: {
      pretty: true,
      indent: '    ',
    },
  });
  return builder.buildObject(xml);
}

export function toObjectAsync(contents: string) {
  return new Parser().parseStringPromise(contents);
}

parseColor = (value: string): Color => {
  const color = value.toUpperCase().replace(/[^0-9A-F]/g, '');

  if (color.length !== 3 && color.length !== 6) {
    console.error(`"${value}" value is not a valid hexadecimal color.`);
    process.exit(1);
  }

  const hex =
    color.length === 3
      ? '#' + color[0] + color[0] + color[1] + color[1] + color[2] + color[2]
      : '#' + color;

  const rgb: Color['rgb'] = {
    red: (parseInt('' + hex[1] + hex[2], 16) / 255).toPrecision(15),
    green: (parseInt('' + hex[3] + hex[4], 16) / 255).toPrecision(15),
    blue: (parseInt('' + hex[5] + hex[6], 16) / 255).toPrecision(15),
  };

  return { hex, rgb };
}

export default createLegacyPlugin({
  packageName: 'expo-splash-screen',
  fallback: [withAndroidSplashScreen, withIosSplashScreen],
});

export type SplashScreenConfig = {
  xxxhdpi?: string;
  xxhdpi?: string;
  xhdpi?: string;
  hdpi?: string;
  mdpi?: string;
  image?: string;
  backgroundColor?: string;
  resizeMode: 'contain' | 'cover' | 'native';
  drawable?: {
    icon: string;
    darkIcon?: string;
  };
  dark?: {
    backgroundColor?: string;
    xxxhdpi?: string;
    xxhdpi?: string;
    xhdpi?: string;
    hdpi?: string;
    mdpi?: string;
    image?: string;
    resizeMode?: 'contain' | 'cover' | 'native';
  };
};

export type AndroidSplashConfig = {
  imageWidth?: number;
} & SplashScreenConfig;

export function getAndroidSplashConfig(
  config: Pick<ExpoConfig, 'splash' | 'android'>,
  props?: AndroidSplashConfig | null
): AndroidSplashConfig | null {
  // Respect the splash screen object, don't mix and match across different splash screen objects
  // in case the user wants the top level splash to apply to every platform except android.
  if (props) {
    const splash = props;
    return {
      xxxhdpi: splash.xxxhdpi ?? splash.image,
      xxhdpi: splash.xxhdpi ?? splash.image,
      xhdpi: splash.xhdpi ?? splash.image,
      hdpi: splash.hdpi ?? splash.image,
      mdpi: splash.mdpi ?? splash.image,
      backgroundColor: splash.backgroundColor,
      resizeMode: splash.resizeMode ?? defaultResizeMode,
      image: splash.image,
      imageWidth: splash.imageWidth ?? 100,
      dark: splash.dark,
      drawable: splash.drawable,
    };
  }

  if (config.android?.splash) {
    const splash = config.android?.splash;
    return {
      xxxhdpi: splash.xxxhdpi ?? splash.image,
      xxhdpi: splash.xxhdpi ?? splash.image,
      xhdpi: splash.xhdpi ?? splash.image,
      hdpi: splash.hdpi ?? splash.image,
      mdpi: splash.mdpi ?? splash.image,
      backgroundColor: splash.backgroundColor,
      image: splash.image,
      resizeMode: splash.resizeMode ?? defaultResizeMode,
      imageWidth: 200,
      dark: splash.dark,
    };
  }

  if (config.splash) {
    const splash = config.splash;
    return {
      xxxhdpi: splash.image,
      xxhdpi: splash.image,
      xhdpi: splash.image,
      hdpi: splash.image,
      mdpi: splash.image,
      image: splash.image,
      backgroundColor: splash.backgroundColor,
      resizeMode: splash.resizeMode ?? defaultResizeMode,
      imageWidth: 200,
      dark: splash.dark,
    };
  }

  return null;
}

export function getAndroidDarkSplashConfig(
  config: Pick<ExpoConfig, 'splash' | 'android'>,
  props?: AndroidSplashConfig | null
): SplashScreenConfig | null {
  if (props?.dark) {
    const splash = props.dark;
    const lightTheme = getAndroidSplashConfig(config, props);
    return {
      xxxhdpi: splash.xxxhdpi ?? splash.image,
      xxhdpi: splash.xxhdpi ?? splash.image,
      xhdpi: splash.xhdpi ?? splash.image,
      hdpi: splash.hdpi ?? splash.image,
      mdpi: splash.mdpi ?? splash.image,
      image: splash.image,
      backgroundColor: splash.backgroundColor,
      resizeMode: lightTheme?.resizeMode ?? defaultResizeMode,
      drawable: props.drawable,
    };
  }

  // Respect the splash screen object, don't mix and match across different splash screen objects
  // in case the user wants the top level splash to apply to every platform except android.
  if (config.android?.splash?.dark) {
    const splash = config.android?.splash?.dark;
    const lightTheme = getAndroidSplashConfig(config, props);
    return {
      xxxhdpi: splash.xxxhdpi ?? splash.image,
      xxhdpi: splash.xxhdpi ?? splash.image,
      xhdpi: splash.xhdpi ?? splash.image,
      hdpi: splash.hdpi ?? splash.image,
      mdpi: splash.mdpi ?? splash.image,
      image: splash.image,
      backgroundColor: splash.backgroundColor,
      // Can't support dark resizeMode because the resize mode is hardcoded into the MainActivity.java
      resizeMode: lightTheme?.resizeMode ?? defaultResizeMode,
    };
  }

  return null;
}

export interface IOSSplashConfig {
  imageWidth?: number;
  image?: string;
  // tabletImage: string | null;
  backgroundColor: string;
  enableFullScreenImage_legacy?: boolean;
  resizeMode: NonNullable<ExpoConfigIosSplash['resizeMode']>;
  tabletImage?: string;
  // TODO: These are here just to test the functionality, the API should be more robust and account for tablet images.
  tabletBackgroundColor?: string;
  dark?: {
    image?: string;
    backgroundColor?: string;
    tabletImage?: string;
    tabletBackgroundColor?: string;
  };
}

export function getIosSplashConfig(
  config: ExpoConfig,
  props: IOSSplashConfig | null
): IOSSplashConfig | null {
  // Respect the splash screen object, don't mix and match across different splash screen objects
  // in case the user wants the top level splash to apply to every platform except iOS.

  // We are using the config plugin
  if (props) {
    const splash = props;
    return {
      image: splash.image,
      resizeMode: splash.resizeMode ?? defaultResizeMode,
      backgroundColor: splash.backgroundColor ?? defaultBackgroundColor,
      tabletImage: splash.tabletImage,
      tabletBackgroundColor: splash.tabletBackgroundColor,
      enableFullScreenImage_legacy: splash.enableFullScreenImage_legacy,
      dark: {
        image: splash.dark?.image,
        backgroundColor: splash.dark?.backgroundColor,
        tabletImage: splash.dark?.tabletImage,
        tabletBackgroundColor: splash.dark?.tabletBackgroundColor,
      },
      imageWidth: splash.imageWidth,
    };
  }

  if (config.ios?.splash) {
    const splash = config.ios?.splash;
    const image = splash.image;
    return {
      image,
      resizeMode: splash.resizeMode ?? defaultResizeMode,
      backgroundColor: splash.backgroundColor ?? defaultBackgroundColor,
      tabletImage: splash.tabletImage,
      tabletBackgroundColor: splash.tabletBackgroundColor,
      enableFullScreenImage_legacy: true,
      dark: {
        image: splash.dark?.image,
        backgroundColor: splash.dark?.backgroundColor,
        tabletImage: splash.dark?.tabletImage,
        tabletBackgroundColor: splash.dark?.tabletBackgroundColor,
      },
      imageWidth: 200,
    };
  }

  if (config.splash) {
    const splash = config.splash;
    const image = splash.image;
    return {
      image,
      resizeMode: splash.resizeMode ?? defaultResizeMode,
      backgroundColor: splash.backgroundColor ?? defaultBackgroundColor,
      enableFullScreenImage_legacy: true,
      imageWidth: 200,
    };
  }

  return {
    backgroundColor: '#ffffff',
    resizeMode: 'contain',
    enableFullScreenImage_legacy: true,
    imageWidth: 200,
  };
}

withAndroidSplashDrawables: ConfigPlugin<Pick<SplashScreenConfig, 'resizeMode'>> = (
  config,
  splash
) => {
  return withDangerousMod(config, [
    'android',
    async (config) => {
      if (splash) {
        await setSplashDrawableAsync(splash, config.modRequest.projectRoot);
      }
      return config;
    },
  ]);
}

export async function setSplashDrawableAsync({ image }: SplashScreenConfig, projectRoot: string) {
  const filePath = (await AndroidConfig.Paths.getResourceXMLPathAsync(projectRoot, {
    name: 'ic_launcher_background',
    kind: 'drawable',
  }))!;

  // Nuke and rewrite the splashscreen.xml drawable
  const xmlContent = {
    'layer-list': {
      $: {
        'xmlns:android': 'http://schemas.android.com/apk/res/android',
      },
      item: [
        {
          $: {
            // TODO: Ensure these keys don't get out of sync
            'android:drawable': '@color/splashscreen_background',
          },
        },
        image && {
          bitmap: [
            {
              $: {
                'android:gravity': 'center',
                // TODO: Ensure these keys don't get out of sync
                'android:src': '@drawable/splashscreen_logo',
              },
            },
          ],
        },
      ].filter(Boolean),
    },
  };
  await XML.writeXMLAsync({ path: filePath, xml: xmlContent });
}

withAndroidSplashImages: ConfigPlugin<AndroidSplashConfig | null> = (
  config,
  splash
) => {
  return withDangerousMod(config, [
    'android',
    async (config) => {
      if (splash) {
        await setSplashImageDrawablesAsync(
          config,
          splash,
          config.modRequest.projectRoot,
          splash?.imageWidth ?? 200
        );
      }
      return config;
    },
  ]);
}

export async function setSplashImageDrawablesAsync(
  config: Pick<ExpoConfig, 'android' | 'splash'>,
  props: AndroidSplashConfig | null,
  projectRoot: string,
  imageWidth: number
) {
  await clearAllExistingSplashImagesAsync(projectRoot);

  const splash = getAndroidSplashConfig(config, props);
  const darkSplash = getAndroidDarkSplashConfig(config, props);

  await Promise.all([
    setSplashImageDrawablesForThemeAsync(splash, 'light', projectRoot, imageWidth),
    setSplashImageDrawablesForThemeAsync(darkSplash, 'dark', projectRoot, imageWidth),
  ]);
}

export async function setSplashImageDrawablesForThemeAsync(
  config: SplashScreenConfig | null,
  theme: 'dark' | 'light',
  projectRoot: string,
  imageWidth: number = 100
) {
  if (!config) return;
  const androidMainPath = path.join(projectRoot, 'android/app/src/main');

  if (config.drawable) {
    await writeSplashScreenDrawablesAsync(androidMainPath, projectRoot, config.drawable);
    return;
  }

  const sizes: DRAWABLE_SIZE[] = ['mdpi', 'hdpi', 'xhdpi', 'xxhdpi', 'xxxhdpi'];

  await Promise.all(
    sizes.map(async (imageKey) => {
      // @ts-ignore
      const image = config[imageKey];

      if (image) {
        const multiplier = DRAWABLES_CONFIGS[imageKey].dimensionsMultiplier;
        const size = imageWidth * multiplier; // "imageWidth" must be replaced by the logo width chosen by the user in its config file
        const canvasSize = 288 * multiplier;

        const background = await generateImageBackgroundAsync({
          width: canvasSize,
          height: canvasSize,
          backgroundColor: config.backgroundColor ?? 'transparent',
          resizeMode: 'cover',
        });

        const { source: foreground } = await generateImageAsync(
          {
            projectRoot,
            cacheType: IMAGE_CACHE_NAME,
          },
          {
            src: image,
            resizeMode: 'contain',
            width: size,
            height: size,
          }
        );

        const composedImage = await compositeImagesAsync({
          background,
          foreground,
          x: (canvasSize - size) / 2,
          y: (canvasSize - size) / 2,
        });

        // Get output path for drawable.
        const outputPath = path.join(
          androidMainPath,
          DRAWABLES_CONFIGS[imageKey].modes[theme].path
        );

        const folder = path.dirname(outputPath);
        // Ensure directory exists.
        await fs.promises.mkdir(folder, { recursive: true });
        await fs.promises.writeFile(outputPath, composedImage);
      }
      return null;
    })
  );
}

