withAndroidSplashLegacyMainActivity: ConfigPlugin<AndroidSplashConfig> = (
  config,
  props
) => {
  return withMainActivity(config, (config) => {
    config.modResults.contents = setSplashScreenLegacyMainActivity(
      config,
      props,
      config.modResults.contents,
      config.modResults.language
    );
    return config;
  });
}

export function setSplashScreenLegacyMainActivity(
  config: Pick<ExpoConfig, 'android' | 'androidStatusBar' | 'userInterfaceStyle'>,
  props: AndroidSplashConfig,
  mainActivity: string,
  language: 'java' | 'kt'
): string {
  debug(`Modify with language: "${language}"`);
  const splashConfig = getAndroidSplashConfig(config, props);

  if (!splashConfig) {
    // Remove our generated code safely...
    const mod = removeContents({
      src: mainActivity,
      tag: SHOW_SPLASH_ID,
    });

    mainActivity = mod.contents;
    if (mod.didClear) {
      debug('Removed SplashScreen.show()');
    }
    return mainActivity;
  }
  // TODO: Translucent is weird
  const statusBarTranslucent = !!config.androidStatusBar?.translucent;

  const { resizeMode } = splashConfig;
  const isJava = language === 'java';
  const LE = isJava ? ';' : '';

  mainActivity = addImports(
    mainActivity,
    [
      'host.exp.exponent.experience.splashscreen.legacy.singletons.SplashScreen',
      'host.exp.exponent.experience.splashscreen.legacy.SplashScreenImageResizeMode',
      'com.facebook.react.ReactRootView',
      'android.os.Bundle',
    ],
    isJava
  );

  if (!mainActivity.match(/(?<=^.*super\.onCreate.*$)/m)) {
    const onCreateBlock = isJava
      ? [
          '    @Override',
          '    protected void onCreate(Bundle savedInstanceState) {',
          '      super.onCreate(savedInstanceState);',
          '    }',
        ]
      : [
          '    override fun onCreate(savedInstanceState: Bundle?) {',
          '      super.onCreate(savedInstanceState)',
          '    }',
        ];

    mainActivity = mergeContents({
      src: mainActivity,
      // insert just below super.onCreate
      anchor: isJava
        ? /(?<=public\s+class\s+.*\s+extends\s+.*\s+{.*$)/m
        : /(?<=class\s+.*\s+:\s+.*\s+{.*$)/m,
      offset: 1,
      comment: '//',
      tag: 'expo-splash-screen-mainActivity-onCreate',
      newSrc: onCreateBlock.join('\n'),
    }).contents;
  }

  // Remove our generated code safely...
  mainActivity = removeContents({
    src: mainActivity,
    tag: SHOW_SPLASH_ID,
  }).contents;

  // Remove code from `@expo/configure-splash-screen`
  mainActivity = mainActivity
    .split('\n')
    .filter((line) => {
      return !/SplashScreen\.show\(this,\s?SplashScreenImageResizeMode\./.test(line);
    })
    .join('\n');

  // Reapply generated code.
  mainActivity = mergeContents({
    src: mainActivity,
    // insert just below super.onCreate
    anchor: /(?<=^.*super\.onCreate.*$)/m,
    offset: 1,
    comment: '//',
    tag: SHOW_SPLASH_ID,
    newSrc: `    SplashScreen.show(this, SplashScreenImageResizeMode.${resizeMode.toUpperCase()}, ReactRootView${
      isJava ? '.class' : '::class.java'
    }, ${statusBarTranslucent})${LE}`,
  }).contents;

  // TODO: Remove old `SplashScreen.show`

  return mainActivity;
}

withAndroidSplashMainActivity: ConfigPlugin<{ isLegacyConfig: boolean }> = (
  config,
  { isLegacyConfig }
) => {
  if (isLegacyConfig) {
    return config;
  }
  return withMainActivity(config, (config) => {
    const { modResults } = config;
    const { language } = modResults;

    const withImports = addImports(
      modResults.contents.replace(
        /(\/\/ )?setTheme\(R\.style\.AppTheme\)/,
        '// setTheme(R.style.AppTheme)'
      ),
      ['expo.modules.splashscreen.SplashScreenManager'],
      language === 'java'
    );

    const init = mergeContents({
      src: withImports,
      comment: '    //',
      tag: 'expo-splashscreen',
      offset: 0,
      anchor: /super\.onCreate\(null\)/,
      newSrc: '    SplashScreenManager.registerOnActivity(this)' + (language === 'java' ? ';' : ''),
    });

    return {
      ...config,
      modResults: {
        ...modResults,
        contents: init.contents,
      },
    };
  });
}

withAndroidSplashScreen: ConfigPlugin<
  AndroidSplashConfig | undefined | null | void
> = (config, props) => {
  const isLegacyConfig = props === undefined;
  const splashConfig = getAndroidSplashConfig(config, props ?? null);

  // Update the android status bar to match the splash screen
  // androidStatusBar applies info to the app activity style.
  const backgroundColor = splashConfig?.backgroundColor || '#ffffff';
  if (config.androidStatusBar?.backgroundColor) {
    if (
      backgroundColor.toLowerCase() !== config.androidStatusBar?.backgroundColor?.toLowerCase?.()
    ) {
      WarningAggregator.addWarningAndroid(
        'androidStatusBar.backgroundColor',
        'Color conflicts with the splash.backgroundColor'
      );
    }
  } else {
    if (!config.androidStatusBar) config.androidStatusBar = {};
    config.androidStatusBar.backgroundColor = backgroundColor;
  }

  return withPlugins(config, [
    [withAndroidSplashMainActivity, { isLegacyConfig }],
    [withAndroidSplashImages, splashConfig],
    [withAndroidSplashDrawables, splashConfig],
    [withAndroidSplashStyles, { splashConfig, isLegacyConfig }],
    [withAndroidSplashStrings, splashConfig],
  ]);
}

withAndroidSplashStrings: ConfigPlugin<AndroidSplashConfig> = (config, props) => {
  return withStringsXml(config, (config) => {
    const splashConfig = getAndroidSplashConfig(config, props);
    if (splashConfig) {
      const { resizeMode } = splashConfig;
      const statusBarTranslucent = !!config.androidStatusBar?.translucent;
      config.modResults = setSplashStrings(config.modResults, resizeMode, statusBarTranslucent);
    }
    return config;
  });
}

export function setSplashStrings(
  strings: AndroidConfig.Resources.ResourceXML,
  resizeMode: string,
  statusBarTranslucent: boolean
): AndroidConfig.Resources.ResourceXML {
  return AndroidConfig.Strings.setStringItem(
    [
      AndroidConfig.Resources.buildResourceItem({
        name: RESIZE_MODE_KEY,
        value: resizeMode,
        translatable: false,
      }),
      AndroidConfig.Resources.buildResourceItem({
        name: STATUS_BAR_TRANSLUCENT_KEY,
        value: String(statusBarTranslucent),
        translatable: false,
      }),
    ],
    strings
  );
}

withAndroidSplashStyles: ConfigPlugin<{
  splashConfig: AndroidSplashConfig | null;
  isLegacyConfig: boolean;
}> = (config, { splashConfig, isLegacyConfig }) => {
  config = withAndroidColors(config, (config) => {
    const backgroundColor = getSplashBackgroundColor(config, splashConfig);
    if (!backgroundColor) {
      return config;
    }
    config.modResults = setSplashColorsForTheme(config.modResults, backgroundColor);
    return config;
  });
  config = withAndroidColorsNight(config, (config) => {
    const backgroundColor = getSplashDarkBackgroundColor(config, splashConfig);
    if (!backgroundColor) {
      return config;
    }
    config.modResults = setSplashColorsForTheme(config.modResults, backgroundColor);
    return config;
  });
  config = withAndroidStyles(config, (config) => {
    config.modResults = removeOldSplashStyleGroup(config.modResults);
    config.modResults = addSplashScreenStyle(config.modResults, isLegacyConfig);
    return config;
  });
  return config;
}

export function removeOldSplashStyleGroup(styles: AndroidConfig.Resources.ResourceXML) {
  const group = {
    name: 'Theme.App.SplashScreen',
    parent: 'Theme.AppCompat.Light.NoActionBar',
  };

  styles.resources.style = styles.resources.style?.filter?.(({ $: head }) => {
    let matches = head.name === group.name;
    if (group.parent != null && matches) {
      matches = head.parent === group.parent;
    }
    return !matches;
  });

  return styles;
}

