   * the `iCloudContainerEnvironment` in the `xcodebuild` `exportOptionsPlist`.
   *
   * Available options: https://developer.apple.com/documentation/bundleresources/entitlements/com_apple_developer_icloud-container-environment
   */
  iCloudContainerEnvironment?: 'Development' | 'Production';
  /**
   * By default, the `com.apple.developer.ubiquity-kvstore-identifier` entitlement is set to a concatenation
   * of your Apple Team ID and the bundle identifier. However, this entitlement may need to reflect a previous Team ID if your
   * app was transferred from another team. Use this option to set this entitlement value manually.
   */
  kvStoreIdentifier?: string;
};

withDocumentPickerIOS: ConfigPlugin<IosProps> = (
  config,
  { iCloudContainerEnvironment, kvStoreIdentifier } = {}
) => {
  return withEntitlementsPlist(config, (config) => {
    config.modResults = setICloudEntitlements(
      config,
      { iCloudContainerEnvironment, kvStoreIdentifier },
      config.modResults
    );
    return config;
  });
}

export function setICloudEntitlements(
  config: Pick<ExpoConfig, 'ios'>,
  { iCloudContainerEnvironment, kvStoreIdentifier }: IosProps,
  { 'com.apple.developer.icloud-container-environment': _env, ...entitlements }: Record<string, any>
): Record<string, any> {
  if (config.ios?.usesIcloudStorage) {
    // Used for AdHoc iOS builds: https://github.com/expo/eas-cli/issues/693
    // https://developer.apple.com/documentation/bundleresources/entitlements/com_apple_developer_icloud-container-environment
    entitlements['com.apple.developer.icloud-container-environment'] = iCloudContainerEnvironment;

    entitlements['com.apple.developer.icloud-container-identifiers'] = [
      `iCloud.${config.ios.bundleIdentifier}`,
    ];
    entitlements['com.apple.developer.ubiquity-container-identifiers'] = [
      `iCloud.${config.ios.bundleIdentifier}`,
    ];
    entitlements['com.apple.developer.ubiquity-kvstore-identifier'] =
      kvStoreIdentifier || `$(TeamIdentifierPrefix)${config.ios.bundleIdentifier}`;

    entitlements['com.apple.developer.icloud-services'] = ['CloudDocuments'];
  }
  return entitlements;
}

export function toValidAndroidResourceName(value: string) {
  const valueWithoutFileExtension = path.parse(value).name;

  const withUnderscores = valueWithoutFileExtension
    .replace(/([a-z])([A-Z])/g, '$1_$2')
    .replace(/([A-Z])([A-Z][a-z])/g, '$1_$2');

  return withUnderscores
    .toLowerCase()
    .replace(/[^a-z0-9]/g, '_')
    .replace(/_+/g, '_');
}

export async function resolveFontPaths(fonts: string[], projectRoot: string) {
  const promises = fonts.map(async (p) => {
    const resolvedPath = path.resolve(projectRoot, p);
    const stat = await fs.stat(resolvedPath);

    if (stat.isDirectory()) {
      const dir = await fs.readdir(resolvedPath);
      return dir.map((file) => path.join(resolvedPath, file));
    }
    return [resolvedPath];
  });
  return (await Promise.all(promises))
    .flat()
    .filter(
      (p) => p.endsWith('.ttf') || p.endsWith('.otf') || p.endsWith('.woff') || p.endsWith('.woff2')
    );
}

export type FontObject = {
  fontFamily: string;
  fontDefinitions: {
    path: string;
    weight: number;
    style?: 'normal' | 'italic' | undefined;
  }[];
};

export type FontProps = {
  fonts?: string[];
  android?: {
    fonts?: Font[];
  };
  ios?: {
    fonts?: string[];
  };
};

withFontsAndroid: ConfigPlugin<Font[]> = (config, fonts) => {
  const assetFontPaths = fonts.filter((it) => typeof it === 'string');
  config = copyFontsToDir(config, assetFontPaths, assetsFontsFir);

  const xmlFonts = fonts.filter((it) => typeof it === 'object');
  config = addXmlFonts(config, xmlFonts);

  return config;
}

export function groupByFamily(array: FontObject[]): GroupedFontObject {
  return array.reduce<GroupedFontObject>((result, item) => {
    const keyValue = item['fontFamily'];
    result[keyValue] ||= [];
    result[keyValue].push(...item.fontDefinitions);
    return result;
  }, {});
}

export function getXmlSpecs(fontsDir: string, xmlFontObjects: GroupedFontObject) {
  return Object.entries(xmlFontObjects).map(([fontFamily, fontDefinitions]) => {
    const filePath = path.join(
      fontsDir,
      `${resourceNameConflictAvoidancePrefix + toValidAndroidResourceName(fontFamily)}.xml`
    );
    // each font family has one xml resource file with potentially multiple font definitions
    // the font files (e.g. ttf) at `path` are copied to res/font
    // with their name changed to be a valid resource and referenced in the xml file
    return {
      path: filePath,
      xml: {
        'font-family': {
          // using `app` namespace for better compat:
          // https://developer.android.com/develop/ui/views/text-and-emoji/fonts-in-xml#using-support-lib
          $: {
            'xmlns:app': 'http://schemas.android.com/apk/res-auto',
          },
          font: fontDefinitions.map((definition) => {
            return {
              $: {
                'app:font': `@font/${toValidAndroidResourceName(definition.path)}`,
                'app:fontStyle': definition.style || 'normal',
                'app:fontWeight': String(definition.weight),
              },
            };
          }),
        },
      },
    };
  });
}

export function generateFontManagerCalls(
  xmlFontObjects: GroupedFontObject,
  language: 'java' | 'kt'
) {
  const lineEnding = language === 'java' ? ';' : '';
  const indent = '    ';

  return Object.keys(xmlFontObjects).map(
    (family) =>
      `${indent}ReactFontManager.getInstance().addCustomFont(this, ${JSON.stringify(family)}, R.font.${resourceNameConflictAvoidancePrefix + toValidAndroidResourceName(family)})${lineEnding}`
  );
}

